import React, { useState } from 'react';
import Map, { Marker, Popup, NavigationControl } from 'react-map-gl/maplibre';
import 'maplibre-gl/dist/maplibre-gl.css';
import { Plane, Truck, MapPin, SlidersHorizontal } from 'lucide-react';

export default function FleetMap({ telemetryData, vehicleById, theme, selectedVehicle, setSelectedVehicle }) {
  // Convert static initial state into a controlled React state
  const [viewState, setViewState] = useState({
    longitude: -122.4194,
    latitude: 37.7749,
    zoom: 15,
    pitch: 65,
    bearing: -20
  });

  // Classic 2D OpenStreetMap tiles, rendered in a 3D environment
  const mapStyle = {
    version: 8,
    sources: {
      osm: {
        type: 'raster',
        tiles: [
          'https://a.tile.openstreetmap.org/{z}/{x}/{y}.png',
          'https://b.tile.openstreetmap.org/{z}/{x}/{y}.png',
          'https://c.tile.openstreetmap.org/{z}/{x}/{y}.png'
        ],
        tileSize: 256,
        attribution: '&copy; OpenStreetMap Contributors'
      }
    },
    layers: [
      {
        id: 'osm',
        type: 'raster',
        source: 'osm',
        minzoom: 0,
        maxzoom: 19
      }
    ]
  };

  return (
    <div style={{ width: '100%', height: '100%', position: 'relative' }}>
      <Map
        {...viewState}
        onMove={evt => setViewState(evt.viewState)}
        mapStyle={mapStyle}
        style={{ width: '100%', height: '100%' }}
      >
        {/* Adds standard zoom buttons and a compass to the top left */}
        <NavigationControl position="top-left" visualizePitch={true} />

        {Object.values(telemetryData).map(pos => {
          const vehicle = vehicleById[pos.vehicle_id];
          if (!vehicle) return null;

          const isGround = vehicle.category === 'GROUND';
          const altitude = isGround ? 0 : (pos.altitude || 50);
          const color = isGround ? 'var(--ground)' : 'var(--accent)';

          return (
            <Marker
              key={pos.vehicle_id}
              longitude={pos.longitude}
              latitude={pos.latitude}
              anchor="bottom"
              onClick={e => { e.originalEvent.stopPropagation(); setSelectedVehicle(vehicle.id); }}
            >
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                <div style={{
                  background: color,
                  color: '#000',
                  borderRadius: '8px',
                  padding: '6px',
                  boxShadow: `0 0 15px ${color}`,
                  transform: `translateY(-${altitude}px)`,
                  transition: 'transform 0.3s ease-out'
                }}>
                  {isGround ? <Truck size={14} /> : <Plane size={14} />}
                </div>

                <div style={{
                  width: '2px',
                  height: `${altitude}px`,
                  background: `linear-gradient(to bottom, ${color}, transparent)`,
                  transition: 'height 0.3s ease-out'
                }} />

                <div style={{
                  width: '12px',
                  height: '4px',
                  background: 'rgba(0,0,0,0.6)',
                  borderRadius: '50%',
                  boxShadow: '0 0 4px rgba(0,0,0,0.8)'
                }} />
              </div>
            </Marker>
          );
        })}

        {selectedVehicle && telemetryData[selectedVehicle] && (
          <Popup
            longitude={telemetryData[selectedVehicle].longitude}
            latitude={telemetryData[selectedVehicle].latitude}
            anchor="top"
            onClose={() => setSelectedVehicle(null)}
            closeButton={false}
          >
            <div className="map-popup">
              <b>{vehicleById[selectedVehicle]?.name}</b>
              <span><MapPin size={11} strokeWidth={2} /> {telemetryData[selectedVehicle].altitude}m</span>
            </div>
          </Popup>
        )}
      </Map>

      {/* Floating Camera Tool Overlay */}
      <div style={{
        position: 'absolute',
        top: '20px',
        right: '20px',
        background: 'var(--bg-glass, rgba(20, 20, 20, 0.85))',
        backdropFilter: 'blur(10px)',
        border: '1px solid var(--border, #333)',
        borderRadius: '12px',
        padding: '16px',
        color: '#fff',
        boxShadow: '0 10px 30px rgba(0,0,0,0.5)',
        zIndex: 10,
        display: 'flex',
        flexDirection: 'column',
        gap: '14px',
        width: '220px'
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', borderBottom: '1px solid var(--border, #333)', paddingBottom: '10px' }}>
          <SlidersHorizontal size={16} color="var(--text-secondary)" />
          <span style={{ fontSize: '14px', fontWeight: '600', margin: 0 }}>Camera Tool</span>
        </div>

        {/* Pitch (Tilt) Slider */}
        <div>
          <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px', color: 'var(--text-secondary, #888)', marginBottom: '6px', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
            <span>Pitch (Tilt)</span>
            <span>{Math.round(viewState.pitch)}°</span>
          </div>
          <input
            type="range"
            min="0"
            max="85"
            value={viewState.pitch}
            onChange={e => setViewState(prev => ({ ...prev, pitch: Number(e.target.value) }))}
            style={{ width: '100%', cursor: 'pointer', accentColor: 'var(--accent, #4f9dff)' }}
          />
        </div>

        {/* Bearing (Rotation) Slider */}
        <div>
          <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px', color: 'var(--text-secondary, #888)', marginBottom: '6px', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
            <span>Bearing</span>
            <span>{Math.round(viewState.bearing)}°</span>
          </div>
          <input
            type="range"
            min="-180"
            max="180"
            value={viewState.bearing}
            onChange={e => setViewState(prev => ({ ...prev, bearing: Number(e.target.value) }))}
            style={{ width: '100%', cursor: 'pointer', accentColor: 'var(--accent, #4f9dff)' }}
          />
        </div>

        {/* Reset Button */}
        <button
          type="button"
          onClick={() => setViewState(prev => ({ ...prev, pitch: 65, bearing: -20 }))}
          style={{
            marginTop: '4px', padding: '8px', background: 'transparent',
            border: '1px solid var(--border, #444)', borderRadius: '6px', color: 'var(--text-secondary, #ccc)',
            fontSize: '12px', cursor: 'pointer', transition: 'all 0.2s ease', fontWeight: '500'
          }}
          onMouseOver={e => { e.currentTarget.style.color = '#fff'; e.currentTarget.style.borderColor = '#888'; }}
          onMouseOut={e => { e.currentTarget.style.color = 'var(--text-secondary)'; e.currentTarget.style.borderColor = 'var(--border)'; }}
        >
          Reset View
        </button>
      </div>
    </div>
  );
}
